import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>
__device__ __forceinline__ float warp_reduce_sum_f32(float val) {
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(mask, val, offset);
    }
    return val;
}
extern "C" __global__
void sdp_fwd_kernel(const __half* __restrict__ Q,
                    const __half* __restrict__ K,
                    const __half* __restrict__ V,
                    __half* __restrict__ Out,
                    int B, int H, int S, int D,
                    float scale)
{
    // Tile two queries per block for better K/V reuse
    const int Q_TILE = 2;
    // Grid mapping:
    // blockIdx.z -> batch index (b)
    // blockIdx.y -> head index (h)
    // blockIdx.x -> query tile index (qi_tile)
    int b = blockIdx.z;
    int h = blockIdx.y;
    int qi_tile = blockIdx.x;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    // Shared memory layout:
    // q_sh[Q_TILE][D]         (float)
    // acc_v_sh[Q_TILE][D]     (float)
    // redbuf[Q_TILE][nwarps]  (float)
    // scalars[Q_TILE][2]      (float) -> [alpha, expv]
    // lmem[Q_TILE]            (float)
    // mmem[Q_TILE]            (float)
    extern __shared__ float smem[];
    int nwarps = (nthreads + 31) >> 5;
    float* base_ptr = smem;
     float* q_sh0 = base_ptr;                  // size D
     float* q_sh1 = q_sh0 + D;                 // size D
     float* red0  = q_sh1 + D;                 // size nwarps
     float* red1  = red0 + nwarps;             // size nwarps
     float* scalars = red1 + nwarps;           // size Q_TILE*2
     float* lmem    = scalars + (2 * Q_TILE);  // size Q_TILE
     float* mmem    = lmem + Q_TILE;           // size Q_TILE
    // Compute base row offset (in rows of length D) for (b,h)
    size_t bh_base_rows = ((size_t)b * (size_t)H + (size_t)h) * (size_t)S;
    // Compute query indices for this tile
    int qi0 = qi_tile * Q_TILE + 0;
    int qi1 = qi_tile * Q_TILE + 1;
    bool valid0 = (qi0 < S);
    bool valid1 = (qi1 < S);
    const __half* q_row0 = valid0 ? (Q + (bh_base_rows + (size_t)qi0) * (size_t)D) : nullptr;
    const __half* q_row1 = valid1 ? (Q + (bh_base_rows + (size_t)qi1) * (size_t)D) : nullptr;
    // Preload Q[qi, :] into shared memory and init shared accumulators
    int D2 = D >> 1;
    const __half2* qh20 = valid0 ? reinterpret_cast<const __half2*>(q_row0) : nullptr;
    const __half2* qh21 = valid1 ? reinterpret_cast<const __half2*>(q_row1) : nullptr;
     const int MAX_SLOTS = 16;
     int slot_idx[MAX_SLOTS];
     int ns = 0;
     for (int i = tid; i < D2; i += nthreads * 2) {
         int i0 = i;
         if (ns < MAX_SLOTS) slot_idx[ns++] = i0;
         int i1_loc = i0 + nthreads;
         if (i1_loc < D2 && ns < MAX_SLOTS) {
             slot_idx[ns++] = i1_loc;
         }
     }
     float acc0_x[MAX_SLOTS], acc0_y[MAX_SLOTS], acc1_x[MAX_SLOTS], acc1_y[MAX_SLOTS];
     for (int si = 0; si < ns; ++si) {
         acc0_x[si] = 0.0f; acc0_y[si] = 0.0f;
         acc1_x[si] = 0.0f; acc1_y[si] = 0.0f;
     }
    for (int i = tid; i < D2; i += nthreads * 2) {
        int i0 = i;
        int d0 = i0 * 2;
        if (valid0) {
            float2 fq0 = __half22float2(qh20[i0]);
            q_sh0[d0]     = fq0.x;
            q_sh0[d0 + 1] = fq0.y;
        } else {
            q_sh0[d0] = 0.0f; q_sh0[d0 + 1] = 0.0f;
        }
        if (valid1) {
            float2 fq1 = __half22float2(qh21[i0]);
            q_sh1[d0]     = fq1.x;
            q_sh1[d0 + 1] = fq1.y;
        } else {
            q_sh1[d0] = 0.0f; q_sh1[d0 + 1] = 0.0f;
        }
         int i1_loc = i0 + nthreads;
         if (i1_loc < D2) {
             int d1 = i1_loc * 2;
             if (valid0) {
                 float2 fq0b = __half22float2(qh20[i1_loc]);
                 q_sh0[d1]     = fq0b.x;
                 q_sh0[d1 + 1] = fq0b.y;
             } else {
                 q_sh0[d1] = 0.0f; q_sh0[d1 + 1] = 0.0f;
             }
             if (valid1) {
                 float2 fq1b = __half22float2(qh21[i1_loc]);
                 q_sh1[d1]     = fq1b.x;
                 q_sh1[d1 + 1] = fq1b.y;
             } else {
                 q_sh1[d1] = 0.0f; q_sh1[d1 + 1] = 0.0f;
             }
         }
    }
    // odd tail of Q and per-thread accumulator for it
    float q_last0 = 0.0f;
    float q_last1 = 0.0f;
    float acc_last0 = 0.0f;
    float acc_last1 = 0.0f;
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        if (valid0) q_last0 = __half2float(q_row0[last]);
        if (valid1) q_last1 = __half2float(q_row1[last]);
    }
    // Initialize running softmax parameters in shared memory
    if (tid < Q_TILE) {
        mmem[tid] = -INFINITY;
        lmem[tid] = 0.0f;
    }
    __syncthreads();
    // Iterate over keys j
    for (int j = 0; j < S; ++j) {
        // Compute dot products s0, s1 = Q[qi,:] . K[j,:]
        const __half* k_row = K + (bh_base_rows + (size_t)j) * (size_t)D;
        const __half2* kh2 = reinterpret_cast<const __half2*>(k_row);
        float local_sum0 = 0.0f;
        float local_sum1 = 0.0f;
        for (int i = tid; i < D2; i += nthreads * 2) {
            int i0 = i;
            int d0 = i0 * 2;
            float2 fk0 = __half22float2(kh2[i0]);
            // accumulate for query 0
            local_sum0 = __fmaf_rn(q_sh0[d0],     fk0.x, local_sum0);
            local_sum0 = __fmaf_rn(q_sh0[d0 + 1], fk0.y, local_sum0);
            // accumulate for query 1
            local_sum1 = __fmaf_rn(q_sh1[d0],     fk0.x, local_sum1);
            local_sum1 = __fmaf_rn(q_sh1[d0 + 1], fk0.y, local_sum1);
            int i1_loc = i0 + nthreads;
            if (i1_loc < D2) {
                int d1 = i1_loc * 2;
                float2 fk1 = __half22float2(kh2[i1_loc]);
                local_sum0 = __fmaf_rn(q_sh0[d1],     fk1.x, local_sum0);
                local_sum0 = __fmaf_rn(q_sh0[d1 + 1], fk1.y, local_sum0);
                local_sum1 = __fmaf_rn(q_sh1[d1],     fk1.x, local_sum1);
                local_sum1 = __fmaf_rn(q_sh1[d1 + 1], fk1.y, local_sum1);
            }
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float k_val = __half2float(k_row[last]);
            local_sum0 = __fmaf_rn(q_last0, k_val, local_sum0);
            local_sum1 = __fmaf_rn(q_last1, k_val, local_sum1);
        }
        // Block-wide reduction of local sums to get totals across the block
        int lane = threadIdx.x & 31;
        int warpId = threadIdx.x >> 5;
        float warp_sum0 = warp_reduce_sum_f32(local_sum0);
        float warp_sum1 = warp_reduce_sum_f32(local_sum1);
        if (lane == 0) {
            red0[warpId] = warp_sum0;
            red1[warpId] = warp_sum1;
        }
        __syncthreads();
        if (tid == 0) {
            float total0 = 0.0f;
            float total1 = 0.0f;
            for (int w = 0; w < nwarps; ++w) {
                total0 += red0[w];
                total1 += red1[w];
            }
            // query 0
            if (valid0) {
                float s0 = total0 * scale;
                float m_prev0 = mmem[0];
                float l_prev0 = lmem[0];
                float m_new0 = fmaxf(m_prev0, s0);
                float a0 = __expf(m_prev0 - m_new0);
                float e0 = __expf(s0 - m_new0);
                float l_new0 = a0 * l_prev0 + e0;
                mmem[0] = m_new0;
                lmem[0] = l_new0;
                scalars[0] = a0;
                scalars[1] = e0;
            } else {
                scalars[0] = 0.0f;
                scalars[1] = 0.0f;
            }
            // query 1
            if (valid1) {
                float s1 = total1 * scale;
                float m_prev1 = mmem[1];
                float l_prev1 = lmem[1];
                float m_new1 = fmaxf(m_prev1, s1);
                float a1 = __expf(m_prev1 - m_new1);
                float e1 = __expf(s1 - m_new1);
                float l_new1 = a1 * l_prev1 + e1;
                mmem[1] = m_new1;
                lmem[1] = l_new1;
                scalars[2] = a1;
                scalars[3] = e1;
            } else {
                scalars[2] = 0.0f;
                scalars[3] = 0.0f;
            }
        }
        __syncthreads();
        float alpha0 = scalars[0];
        float expv0  = scalars[1];
        float alpha1 = scalars[2];
        float expv1  = scalars[3];
        // Update accumulators
         const __half* v_row = V + (bh_base_rows + (size_t)j) * (size_t)D;
         const __half2* vh2 = reinterpret_cast<const __half2*>(v_row);
         for (int si = 0; si < ns; ++si) {
             int i_loc = slot_idx[si];
             float2 fv0 = __half22float2(vh2[i_loc]);
             float c0x = expv0 * fv0.x;
             float c0y = expv0 * fv0.y;
             float c1x = expv1 * fv0.x;
             float c1y = expv1 * fv0.y;
             if (valid0) {
                 acc0_x[si] = __fmaf_rn(alpha0, acc0_x[si], c0x);
                 acc0_y[si] = __fmaf_rn(alpha0, acc0_y[si], c0y);
             }
             if (valid1) {
                 acc1_x[si] = __fmaf_rn(alpha1, acc1_x[si], c1x);
                 acc1_y[si] = __fmaf_rn(alpha1, acc1_y[si], c1y);
             }
         }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float v_val = __half2float(v_row[last]);
            if (valid0) acc_last0 = __fmaf_rn(alpha0, acc_last0, expv0 * v_val);
            if (valid1) acc_last1 = __fmaf_rn(alpha1, acc_last1, expv1 * v_val);
        }
        __syncthreads();
    }
    // Normalize by l and write output
    if (valid0) {
        float l_val0 = lmem[0];
        float inv_l0 = 1.0f / l_val0;
        __half* out_row0 = Out + (bh_base_rows + (size_t)qi0) * (size_t)D;
        __half2* out_h20 = reinterpret_cast<__half2*>(out_row0);
         for (int si = 0; si < ns; ++si) {
             int i_loc = slot_idx[si];
             float2 f0;
             f0.x = acc0_x[si] * inv_l0;
             f0.y = acc0_y[si] * inv_l0;
             out_h20[i_loc] = __floats2half2_rn(f0.x, f0.y);
         }
         // padding to preserve original line count








        if ((D & 1) && tid == 0) {
            int last = D - 1;
            out_row0[last] = __float2half_rn(acc_last0 * inv_l0);
        }
    }
    if (valid1) {
        float l_val1 = lmem[1];
        float inv_l1 = 1.0f / l_val1;
        __half* out_row1 = Out + (bh_base_rows + (size_t)qi1) * (size_t)D;
        __half2* out_h21 = reinterpret_cast<__half2*>(out_row1);
         for (int si = 0; si < ns; ++si) {
             int i_loc = slot_idx[si];
             float2 f0;
             f0.x = acc1_x[si] * inv_l1;
             f0.y = acc1_y[si] * inv_l1;
             out_h21[i_loc] = __floats2half2_rn(f0.x, f0.y);
         }








        if ((D & 1) && tid == 0) {
            int last = D - 1;
            out_row1[last] = __float2half_rn(acc_last1 * inv_l1);
        }
    }
}
torch::Tensor sdp_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda(), "Q must be a CUDA tensor");
    TORCH_CHECK(K.is_cuda(), "K must be a CUDA tensor");
    TORCH_CHECK(V.is_cuda(), "V must be a CUDA tensor");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16 (Half)");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16 (Half)");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16 (Half)");
    TORCH_CHECK(Q.sizes() == K.sizes(), "Q and K must have the same shape");
    TORCH_CHECK(Q.sizes() == V.sizes(), "Q and V must have the same shape");
    TORCH_CHECK(Q.dim() == 4, "Expected Q to have shape [B, H, S, D]");
    auto B = (int)Q.size(0);
    auto H = (int)Q.size(1);
    auto S = (int)Q.size(2);
    auto D = (int)Q.size(3);
    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();
    auto Out = torch::empty_like(Qc);
    const __half* Qp = reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>());
    const __half* Kp = reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>());
    const __half* Vp = reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>());
    __half* Outp = reinterpret_cast<__half*>(Out.data_ptr<at::Half>());
    const int Q_TILE = 2;
    dim3 grid((unsigned)((S + Q_TILE - 1) / Q_TILE), (unsigned)H, (unsigned)B);
    int block = 128;
    int warps = (block + 31) / 32;
     size_t shmem = (size_t)Q_TILE * (size_t)D * sizeof(float)      // q_sh
                  + (size_t)Q_TILE * (size_t)warps * sizeof(float)  // redbuf
                  + (size_t)(Q_TILE * 2 * sizeof(float))            // scalars (alpha,expv)
                  + (size_t)(Q_TILE * 2 * sizeof(float));           // l + m
    float scale = 1.0f / sqrtf((float)D);
    auto stream = at::cuda::getCurrentCUDAStream();
    sdp_fwd_kernel<<<grid, block, shmem, stream.stream()>>>(Qp, Kp, Vp, Outp, B, H, S, D, scale);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return Out;
}
