    int D2 = D >> 1;
    const __half2* qh2 = reinterpret_cast<const __half2*>(q_row);
    for (int i = tid; i < D2; i += nthreads * 2) {
        int i0 = i;
        float2 fq0 = __half22float2(qh2[i0]);
        int d0 = i0 * 2;
        q_sh[d0]     = fq0.x;
        q_sh[d0 + 1] = fq0.y;
        acc_v_sh[d0]     = 0.0f;
        acc_v_sh[d0 + 1] = 0.0f;
