        if (i1 < D2) {
            float2 fq1 = __half22float2(qh2[i1]);
            int d1 = i1 * 2;
            q_sh[d1]     = fq1.x;
            q_sh[d1 + 1] = fq1.y;
            acc_v_sh[d1]     = 0.0f;
            acc_v_sh[d1 + 1] = 0.0f;
